import { z } from 'zod'
import { PLUGIN_MANIFEST_V2_SINCE, pluginFieldDoc } from '../manifest/plugin-schema-field-docs'
import {
  tolerantPluginThemeBackgroundRegistration,
  pluginThemeBackgroundSchema,
  tolerantPluginThemeBackground,
  type PluginThemeBackgroundArtifact
} from './plugin-theme-background'

// Why: this is a public, additive-only theme API. Exposing every main.css
// variable would make internal renderer refactors plugin-breaking changes.
export const PLUGIN_APP_THEME_TOKENS = [
  '--background',
  '--editor-surface',
  '--foreground',
  '--card',
  '--card-foreground',
  '--popover',
  '--popover-foreground',
  '--primary',
  '--primary-foreground',
  '--secondary',
  '--secondary-foreground',
  '--muted',
  '--muted-foreground',
  '--accent',
  '--accent-foreground',
  '--border',
  '--input',
  '--ring',
  '--chart-1',
  '--chart-2',
  '--chart-3',
  '--chart-4',
  '--chart-5',
  '--sidebar',
  '--sidebar-foreground',
  '--sidebar-primary',
  '--sidebar-primary-foreground',
  '--sidebar-accent',
  '--sidebar-accent-foreground',
  '--sidebar-border',
  '--sidebar-ring',
  '--worktree-sidebar',
  '--worktree-sidebar-foreground',
  '--worktree-sidebar-accent',
  '--worktree-sidebar-accent-foreground',
  '--worktree-sidebar-border',
  '--worktree-sidebar-ring',
  '--worktree-sidebar-active',
  '--worktree-sidebar-active-border',
  '--host-badge',
  '--host-badge-foreground',
  '--tab-bar',
  '--tab-active',
  '--tab-active-foreground',
  '--tab-active-indicator',
  '--tab-inactive',
  '--tab-inactive-foreground',
  '--split-divider',
  '--split-divider-hover',
  '--chat-user-message',
  '--text-link',
  '--diff-added',
  '--diff-added-background',
  '--diff-added-emphasis',
  '--diff-added-gutter',
  '--diff-removed',
  '--diff-removed-background',
  '--diff-removed-emphasis',
  '--diff-removed-gutter',
  '--git-decoration-added',
  '--git-decoration-modified',
  '--git-decoration-deleted',
  '--git-decoration-renamed',
  '--git-decoration-untracked',
  '--git-decoration-copied',
  '--git-decoration-ignored'
] as const

const THEME_TOKEN_SET = new Set<string>(PLUGIN_APP_THEME_TOKENS)

/** Every theme sets these; the rest are optional and derived from them when omitted. */
export const PLUGIN_APP_THEME_REQUIRED_TOKENS = ['--background', '--foreground'] as const

// Why: an omitted token would otherwise keep the built-in value and clash with the theme's
// palette (e.g. a neutral grey selected row on a purple theme). A rule names source tokens
// (first present wins) or mixes the theme's foreground into its background (or `into`); the
// renderer's contrast check still drops any derived pair that ends up unreadable.
export type PluginThemeDerivationRule = readonly string[] | { mixForeground: number; into?: string }

const DERIVED_TOKENS: Record<string, PluginThemeDerivationRule> = {
  '--editor-surface': ['--background'],
  '--card': ['--background'],
  '--card-foreground': ['--foreground'],
  '--popover': ['--card', '--background'],
  '--popover-foreground': ['--card-foreground', '--foreground'],
  '--primary': ['--foreground'],
  '--primary-foreground': ['--background'],
  '--muted': ['--secondary'],
  '--secondary': ['--muted'],
  '--muted-foreground': { mixForeground: 70 },
  '--border': { mixForeground: 16 },
  '--accent': { mixForeground: 12 },
  '--accent-foreground': ['--foreground'],
  '--secondary-foreground': ['--foreground'],
  '--input': ['--border'],
  '--ring': ['--primary'],
  // Why a lift: Orca draws no line between the left sidebar and the canvas; the surface step is
  // the divider, so a sidebar equal to the background leaves no edge at all.
  '--sidebar': { mixForeground: 8 },
  '--sidebar-foreground': ['--foreground'],
  '--sidebar-primary': ['--primary'],
  '--sidebar-primary-foreground': ['--primary-foreground'],
  '--sidebar-accent': ['--accent'],
  '--sidebar-accent-foreground': ['--accent-foreground'],
  '--sidebar-border': ['--border'],
  '--sidebar-ring': ['--ring'],
  '--worktree-sidebar': ['--sidebar'],
  '--worktree-sidebar-foreground': ['--sidebar-foreground'],
  '--worktree-sidebar-accent': ['--sidebar-accent'],
  '--worktree-sidebar-accent-foreground': ['--sidebar-accent-foreground'],
  '--worktree-sidebar-border': ['--sidebar-border'],
  '--worktree-sidebar-ring': ['--sidebar-ring'],
  '--chart-1': ['--primary']
}

/** Fills omitted tokens from the ones the theme set, in dependency order. */
export function completePluginAppThemeTokens(
  tokens: Record<string, string>
): Record<string, string> {
  const complete = { ...tokens }
  for (const [token, rule] of Object.entries(DERIVED_TOKENS)) {
    if (complete[token]) {
      continue
    }
    const derived =
      'mixForeground' in rule
        ? `color-mix(in srgb, ${complete['--foreground']} ${rule.mixForeground}%, ${complete['--background']})`
        : rule.map((source) => complete[source]).find(Boolean)
    if (derived) {
      complete[token] = derived
    }
  }
  return complete
}

const NON_COLOR_KEYWORDS = new Set([
  'transparent',
  'currentcolor',
  'inherit',
  'initial',
  'unset',
  'revert',
  'revert-layer',
  'none'
])

// Why: values land in CSS custom properties, so only color syntax is accepted: hex, a color
// function, or a bare color name. The renderer also requires CSS.supports('color', value).
function isThemeColorValue(value: string): boolean {
  const normalized = value.trim().toLowerCase()
  return (
    normalized.length <= 64 &&
    !NON_COLOR_KEYWORDS.has(normalized) &&
    (/^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/.test(normalized) ||
      /^(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch)\([0-9.,%/ +-]*(?:deg|turn|rad)?[0-9.,%/ +-]*\)$/.test(
        normalized
      ) ||
      /^[a-z]{3,20}$/.test(normalized))
  )
}

const themeFields = {
  base: z.enum(['light', 'dark']),
  tokens: z.record(
    z.string().refine((token) => THEME_TOKEN_SET.has(token), 'is not a public theme token'),
    z.string().refine(isThemeColorValue, 'must be a color value')
  )
}

// Why VS Code's shape: authors can paste a VS Code theme's `tokenColors` unchanged.
const TOKEN_FONT_STYLE =
  /^(?:(?:italic|bold|underline|strikethrough)(?: (?:italic|bold|underline|strikethrough))*)?$/
const tokenColorScope = z.string().min(1).max(512)
const tokenColorRuleFields = {
  name: z.string().max(256).optional(),
  scope: z.union([tokenColorScope, z.array(tokenColorScope).min(1).max(64)]),
  settings: z.strictObject({
    foreground: z
      .string()
      .regex(/^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i, 'must be a hex color')
      .optional(),
    fontStyle: z
      .string()
      .regex(TOKEN_FONT_STYLE, 'must be italic, bold, underline or strikethrough')
      .optional()
  })
}
const tokenColorRuleSchema = z.strictObject(tokenColorRuleFields)
const MAX_TOKEN_COLOR_RULES = 512
const tokenColorsSchema = z
  .array(tokenColorRuleSchema)
  .max(MAX_TOKEN_COLOR_RULES)
  .meta(
    pluginFieldDoc(
      "Code colors by TextMate scope, in VS Code's `tokenColors` shape.",
      PLUGIN_MANIFEST_V2_SINCE
    )
  )
export type PluginThemeTokenColorRule = z.infer<typeof tokenColorRuleSchema>

/** Runtime keeps the rules it understands, so one malformed or newer rule never drops the theme. */
function tolerantTokenColors(value: unknown): PluginThemeTokenColorRule[] | undefined {
  if (!Array.isArray(value)) {
    return undefined
  }
  const ruleSchema = z.object({
    ...tokenColorRuleFields,
    settings: z.object(tokenColorRuleFields.settings.shape)
  })
  return value.slice(0, MAX_TOKEN_COLOR_RULES).flatMap((rule) => {
    const parsed = ruleSchema.safeParse(rule)
    return parsed.success
      ? [{ scope: parsed.data.scope, settings: { ...parsed.data.settings } }]
      : []
  })
}

const hasRequiredTokens = (theme: { tokens: Record<string, string> }): boolean =>
  PLUGIN_APP_THEME_REQUIRED_TOKENS.every((token) => theme.tokens[token])

/** `validate:plugin` refuses unknown keys; shipped clients skip them, so a token or slot added
 *  later never fails a whole theme on an older Orca. */
export type PluginArtifactStrictness = 'strict' | 'tolerant'

/** Keeps only `known` keys of an object; anything else passes through for the schema to reject. */
export function pickKnownArtifactKeys(known: ReadonlySet<string>) {
  return (value: unknown): unknown =>
    typeof value === 'object' && value !== null && !Array.isArray(value)
      ? Object.fromEntries(Object.entries(value).filter(([key]) => known.has(key)))
      : value
}

function pluginAppThemeArtifactSchema(strictness: PluginArtifactStrictness) {
  const fields = {
    schemaVersion: z.literal(1).optional(),
    base: themeFields.base,
    tokens:
      strictness === 'strict'
        ? themeFields.tokens
        : z.preprocess(pickKnownArtifactKeys(THEME_TOKEN_SET), themeFields.tokens),
    tokenColors: (strictness === 'strict'
      ? tokenColorsSchema
      : z.unknown().transform(tolerantTokenColors)
    ).optional(),
    background: (strictness === 'strict'
      ? pluginThemeBackgroundSchema
      : z.unknown().transform(tolerantPluginThemeBackground)
    ).optional()
  }
  return (strictness === 'strict' ? z.strictObject(fields) : z.object(fields)).refine(
    hasRequiredTokens,
    `must define ${PLUGIN_APP_THEME_REQUIRED_TOKENS.join(' and ')}`
  )
}

/** Host-owned id; plugin keys keep ids from colliding across publishers. */
export const pluginContentIdSchema = z.templateLiteral(['plugin:', z.string()])

// Why looser values here: the host adds derived color-mix() values; the renderer still accepts
// only what CSS parses as a color and checks contrast before painting.
const registrationTokenValueSchema = z
  .string()
  .max(256)
  .refine((value) => !/url\(|var\(|[;{}\\]/i.test(value), 'must be a color value')

const pluginThemeRegistrationSchema = z
  .object({
    base: themeFields.base,
    tokens: z.record(
      z.string().refine((token) => THEME_TOKEN_SET.has(token)),
      registrationTokenValueSchema
    ),
    tokenColors: tokenColorsSchema.optional(),
    background: tolerantPluginThemeBackgroundRegistration,
    id: pluginContentIdSchema,
    /** Changes whenever the theme's content does, so a cached paint can be checked. */
    revision: z.string().max(128),
    pluginKey: z.string(),
    pluginName: z.string(),
    label: z.string()
  })
  .refine(hasRequiredTokens)

export type PluginAppThemeArtifact = Pick<
  PluginThemeRegistration,
  'base' | 'tokens' | 'tokenColors'
> & { background?: PluginThemeBackgroundArtifact }
export type PluginThemeRegistration = z.infer<typeof pluginThemeRegistrationSchema>

/** Parses a theme and fills its omitted tokens. */
export function parsePluginAppThemeArtifact(
  raw: string,
  strictness: PluginArtifactStrictness = 'tolerant'
): PluginAppThemeArtifact {
  const theme = pluginAppThemeArtifactSchema(strictness).parse(JSON.parse(raw))
  return {
    base: theme.base,
    tokens: completePluginAppThemeTokens(theme.tokens),
    ...(theme.tokenColors?.length ? { tokenColors: theme.tokenColors } : {}),
    ...(theme.background ? { background: theme.background } : {})
  }
}

export function isPluginThemeRegistration(value: unknown): value is PluginThemeRegistration {
  return pluginThemeRegistrationSchema.safeParse(value).success
}

import {
  pluginAppThemeCssFallback,
  type PluginThemeCssFallbackRule
} from '../../../shared/plugins/artifacts/plugin-theme-css-fallbacks'

/** sRGB channels 0-255 and alpha 0-1, or null when the value is not a CSS color. */
export type ColorProbe = (value: string) => readonly [number, number, number, number] | null
export type Rgba = readonly [number, number, number, number]

type ContrastRule = {
  surface: string
  text: string
  min: number
  /** What a failure drops, when not both sides: never a shared token this check must not cost. */
  drop?: readonly string[]
  /** A translucent surface is checked as painted over this opaque one. */
  over?: string
  /** Also dropped when the theme omitted the surface, which then follows this token. */
  surfaceSource?: string
}

const MIN_TEXT_CONTRAST = 4.5
// Why 3:1: status hues tint file names, and Orca's own light ignored color is 3.3:1.
const MIN_STATUS_TEXT_CONTRAST = 3
const textPair = (surface: string, text: string): ContrastRule => ({
  surface,
  text,
  min: MIN_TEXT_CONTRAST
})
const GIT_DECORATIONS = [
  'added',
  'modified',
  'deleted',
  'renamed',
  'untracked',
  'copied',
  'ignored'
]

// Why: a theme must not be able to hide text, so every text/surface pair keeps WCAG AA contrast.
const CONTRAST_RULE_DEFINITIONS: readonly ContrastRule[] = [
  textPair('--background', '--foreground'),
  textPair('--background', '--muted-foreground'),
  // Notebook markdown renders directly on the editor surface.
  textPair('--editor-surface', '--foreground'),
  textPair('--editor-surface', '--muted-foreground'),
  textPair('--card', '--card-foreground'),
  textPair('--popover', '--popover-foreground'),
  textPair('--primary', '--primary-foreground'),
  textPair('--secondary', '--secondary-foreground'),
  textPair('--muted', '--muted-foreground'),
  textPair('--accent', '--accent-foreground'),
  textPair('--sidebar', '--sidebar-foreground'),
  textPair('--sidebar-primary', '--sidebar-primary-foreground'),
  textPair('--sidebar-accent', '--sidebar-accent-foreground'),
  textPair('--worktree-sidebar', '--worktree-sidebar-foreground'),
  textPair('--worktree-sidebar-accent', '--worktree-sidebar-accent-foreground'),
  {
    ...textPair('--worktree-sidebar-active', '--worktree-sidebar-foreground'),
    drop: ['--worktree-sidebar-active'],
    over: '--worktree-sidebar'
  },
  { ...textPair('--host-badge', '--host-badge-foreground'), over: '--worktree-sidebar' },
  textPair('--tab-active', '--tab-active-foreground'),
  textPair('--tab-inactive', '--tab-inactive-foreground'),
  // Hovered inactive tabs take the active text color.
  textPair('--tab-inactive', '--tab-active-foreground'),
  {
    ...textPair('--chat-user-message', '--chat-foreground-strong'),
    drop: ['--chat-user-message'],
    over: '--chat-canvas'
  },
  ...['added', 'removed'].flatMap((side): ContrastRule[] => {
    const tint = (kind: string): ContrastRule => ({
      ...textPair(`--diff-${side}-${kind}`, '--foreground'),
      drop: [`--diff-${side}-${kind}`],
      surfaceSource: `--diff-${side}`,
      over: '--editor-surface'
    })
    // Chat diff rows paint the hue-mixed text on the line tint over the chat canvas.
    return [
      tint('background'),
      tint('emphasis'),
      { ...tint('background'), text: `--chat-diff-${side}`, over: '--chat-canvas' }
    ]
  }),
  { ...textPair('--editor-surface', '--text-link'), drop: ['--text-link'] },
  ...GIT_DECORATIONS.map((status): ContrastRule => ({
    surface: '--sidebar',
    text: `--git-decoration-${status}`,
    min: MIN_STATUS_TEXT_CONTRAST,
    drop: [`--git-decoration-${status}`]
  }))
]
const CONTRAST_RULES = CONTRAST_RULE_DEFINITIONS.map((rule) => ({
  ...rule,
  dropped: rule.drop ?? [rule.surface, rule.text]
}))
// Why 2:1, not WCAG's 3:1: Orca's own light ring is 2.6:1; the goal is a ring that never vanishes.
const RINGS: readonly (readonly [string, string])[] = [
  ['--ring', '--background'],
  ['--sidebar-ring', '--sidebar'],
  ['--worktree-sidebar-ring', '--worktree-sidebar'],
  ['--tab-active-indicator', '--tab-active']
]
const MIN_RING_CONTRAST = 2
// Why a floor, not opaque: Orca's own dark borders are 7% white; 0 or near-0 alpha hides them.
const BORDERS = [
  '--border',
  '--input',
  '--sidebar-border',
  '--worktree-sidebar-border',
  '--worktree-sidebar-active-border',
  '--split-divider',
  '--split-divider-hover'
]
const MIN_BORDER_ALPHA = 0.05

function luminance([r, g, b]: Rgba): number {
  const channel = (value: number): number => {
    const c = value / 255
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4
  }
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

/** WCAG contrast ratio between two opaque colors. */
export function contrastRatio(a: Rgba, b: Rgba): number {
  const first = luminance(a)
  const second = luminance(b)
  return (Math.max(first, second) + 0.05) / (Math.min(first, second) + 0.05)
}

function over([r, g, b, a]: Rgba, [br, bg, bb]: Rgba): Rgba {
  return [r * a + br * (1 - a), g * a + bg * (1 - a), b * a + bb * (1 - a), 1]
}

/** `color-mix(in srgb, a percent%, b)`. */
function mix(a: Rgba, b: Rgba, percent: number): Rgba {
  const p = percent / 100
  const channel = (index: 0 | 1 | 2 | 3): number => a[index] * p + b[index] * (1 - p)
  return [channel(0), channel(1), channel(2), channel(3)]
}

/**
 * The plugin tokens that are safe to paint over the built-in ones for the theme's base.
 * Checks run on the effective set (plugin values, else what main.css derives from them, else
 * built-in), and dropping a token can expose a value that breaks another pair, so checks repeat
 * until nothing changes. Dropped tokens keep their built-in values.
 */
export function safePluginThemeTokens(
  tokens: Readonly<Record<string, string>>,
  base: 'light' | 'dark',
  builtIns: Readonly<Record<string, string>>,
  probe: ColorProbe
): Record<string, string> {
  const accepted = new Map<string, Rgba>()
  for (const [token, value] of Object.entries(tokens)) {
    const color = probe(value)
    if (color && !(BORDERS.includes(token) && color[3] < MIN_BORDER_ALPHA)) {
      accepted.set(token, color)
    }
  }
  const builtInColors = new Map<string, Rgba | null>()
  const derived = (rule: PluginThemeCssFallbackRule): Rgba | null => {
    if ('tint' in rule) {
      const hue = effective(rule.tint)
      return hue ? [hue[0], hue[1], hue[2], (hue[3] * rule.percent) / 100] : null
    }
    if (!('mixForeground' in rule)) {
      return rule.map(effective).find(Boolean) ?? null
    }
    const foreground = effective('--foreground')
    const into = effective(rule.into ?? '--background')
    return foreground && into ? mix(foreground, into, rule.mixForeground) : null
  }
  function effective(token: string): Rgba | null {
    const own = accepted.get(token)
    if (own) {
      return own
    }
    const fallback = pluginAppThemeCssFallback(token, base)
    if (fallback) {
      return derived(fallback)
    }
    if (!builtInColors.has(token)) {
      builtInColors.set(token, builtIns[token] ? probe(builtIns[token]) : null)
    }
    return builtInColors.get(token) ?? null
  }
  const drop = (...pair: string[]): boolean =>
    pair.map((token) => accepted.delete(token)).some(Boolean)

  for (let changed = true; changed;) {
    changed = false
    for (const rule of CONTRAST_RULES) {
      const dropped =
        rule.surfaceSource && tokens[rule.surface] === undefined
          ? [...rule.dropped, rule.surfaceSource]
          : rule.dropped
      // Why skip: a check with nothing of the theme's to drop can't change the result, so a
      // theme that sets none of a check's tokens pays no probes for it.
      if (!dropped.some((token) => accepted.has(token))) {
        continue
      }
      const textColor = effective(rule.text)
      const ownSurface = effective(rule.surface)
      const beneath = rule.over ? effective(rule.over) : null
      const surfaceColor = ownSurface && beneath?.[3] === 1 ? over(ownSurface, beneath) : ownSurface
      if (
        surfaceColor &&
        textColor &&
        (surfaceColor[3] < 1 ||
          textColor[3] < 1 ||
          contrastRatio(surfaceColor, textColor) < rule.min)
      ) {
        changed = drop(...dropped) || changed
      }
    }
    for (const [ring, surface] of RINGS) {
      const ringColor = accepted.get(ring)
      if (!ringColor) {
        continue
      }
      const surfaceColor = effective(surface)
      if (
        surfaceColor &&
        contrastRatio(over(ringColor, surfaceColor), surfaceColor) < MIN_RING_CONTRAST
      ) {
        changed = drop(ring) || changed
      }
    }
  }
  return Object.fromEntries(Object.entries(tokens).filter(([token]) => accepted.has(token)))
}

let probeContext: OffscreenCanvasRenderingContext2D | null | undefined

/** Resolves a color through the browser's own parser by painting one pixel. */
export const browserColorProbe: ColorProbe = (value) => {
  if (typeof CSS === 'undefined' || !CSS.supports('color', value)) {
    return null
  }
  probeContext ??=
    typeof OffscreenCanvas === 'undefined'
      ? null
      : new OffscreenCanvas(1, 1).getContext('2d', { willReadFrequently: true })
  if (!probeContext) {
    return null
  }
  const context = probeContext
  // Why two seeds: fillStyle silently keeps its old value for values it rejects (e.g. `inherit`).
  const paint = (seed: string): number[] => {
    context.clearRect(0, 0, 1, 1)
    context.fillStyle = seed
    context.fillStyle = value
    context.fillRect(0, 0, 1, 1)
    return [...context.getImageData(0, 0, 1, 1).data]
  }
  const first = paint('#000000')
  const second = paint('#ffffff')
  if (first.some((channel, index) => channel !== second[index])) {
    return null
  }
  const [r = 0, g = 0, b = 0, a = 0] = first
  return [r, g, b, a / 255]
}

import type { PluginThemeDerivationRule } from './plugin-theme-artifact'

/** A derivation, or `tint`: `color-mix(in srgb, <tint> <percent>%, transparent)`. */
export type PluginThemeCssFallbackRule =
  | PluginThemeDerivationRule
  | { tint: string; percent: number }

const tint = (token: string, light: number, dark: number) => ({
  light: { tint: token, percent: light },
  dark: { tint: token, percent: dark }
})

/**
 * What main.css paints for a token the theme omits (or the contrast check drops), derived from
 * whatever the theme did paint. Never painted; the contrast check and the token reference read
 * it. Internal chat colors appear so the chat bubble is checked against its real text. Keep in
 * sync with main.css.
 */
const PLUGIN_APP_THEME_CSS_FALLBACKS: Record<
  string,
  PluginThemeCssFallbackRule | Record<'light' | 'dark', PluginThemeCssFallbackRule>
> = {
  '--tab-bar': ['--card'],
  // Why per base: a white light --card can't be lifted, so light recesses the inactive tabs.
  '--tab-active': { light: ['--tab-bar'], dark: { mixForeground: 6, into: '--tab-bar' } },
  '--tab-active-foreground': ['--foreground'],
  '--tab-active-indicator': ['--tab-active-foreground'],
  '--tab-inactive': { light: { mixForeground: 4, into: '--tab-bar' }, dark: ['--tab-bar'] },
  '--tab-inactive-foreground': ['--muted-foreground'],
  '--host-badge': { light: ['--accent'], dark: { tint: '--accent', percent: 80 } },
  '--host-badge-foreground': ['--muted-foreground'],
  '--diff-added': ['--git-decoration-added'],
  '--diff-removed': ['--git-decoration-deleted'],
  '--diff-added-background': tint('--diff-added', 13, 16),
  '--diff-added-emphasis': tint('--diff-added', 15, 20),
  '--diff-added-gutter': tint('--diff-added', 26, 30),
  '--diff-removed-background': tint('--diff-removed', 11, 18),
  '--diff-removed-emphasis': tint('--diff-removed', 15, 20),
  '--diff-removed-gutter': tint('--diff-removed', 22, 32),
  '--chat-diff-added': { mixForeground: 30, into: '--diff-added' },
  '--chat-diff-removed': { mixForeground: 30, into: '--diff-removed' },
  // At the default chat contrast setting.
  '--chat-canvas': { light: ['--background'], dark: { mixForeground: 5 } },
  '--chat-foreground-strong': {
    light: { mixForeground: 92, into: '--chat-canvas' },
    dark: { mixForeground: 90, into: '--chat-canvas' }
  }
}

export function pluginAppThemeCssFallback(
  token: string,
  base: 'light' | 'dark'
): PluginThemeCssFallbackRule | undefined {
  const rule = PLUGIN_APP_THEME_CSS_FALLBACKS[token]
  return rule && 'light' in rule ? rule[base] : rule
}

